<!--vbase-->
<template>
  <q-page class="row items-center justify-evenly container-fluid">
    <VueFlow
      v-model="elements"
      class="basicflow"
      :default-edge-options="{ type: 'smoothstep' }"
      :default-zoom="1.5"
      :min-zoom="0.2"
      :max-zoom="4"
      :fit-view-on-init="true"
    >
      <Background pattern-color="#aaa" :gap="6" />
      <MiniMap />
      <Controls>
        <div>
          <q-btn
            flat
            data-cy="add"
            :label="$t('Add')"
            text-color="primary"
            color="white"
            @click="addNodes = true"
          />
        </div>
        <div>
          <q-btn
            flat
            data-cy="remove"
            :label="$t('Delete')"
            text-color="primary"
            color="white"
            @click="removeNodes()"
          />
        </div>
        <div>
          <q-btn
            flat
            data-cy="save"
            :label="$t('save')"
            text-color="primary"
            color="white"
            @click="saveFlow()"
          />
        </div>
        <div>
          <q-btn
            flat
            data-cy="import"
            :label="$t('Import')"
            text-color="primary"
            color="white"
            @click="importNodes = true"
          />
        </div>
        <div>
          <q-btn
            flat
            data-cy="run"
            :label="$t('Run')"
            text-color="primary"
            color="white"
            @click="runVisual()"
          />
        </div>
        <div>
          <q-btn
            flat
            data-cy="format"
            :label="$t('Format')"
            text-color="primary"
            color="white"
            @click="sortNodes()"
          />
        </div>
      </Controls>
      <q-dialog v-model="addNodes">
        <q-card>
          <q-card-section class="row items-center">
            <div>
              <div style="width: 130px; margin-right: 30px">
                <div>Create new Node</div>
              </div>
              <div style="width: 100%">
                <q-select
                  v-model="nodetype"
                  :options="nodetypes"
                  :label="$t('Nodetype')"
                />
              </div>
              <div style="width: 100%">
                <q-input v-model="nodename" :label="$t('Nodename')" />
              </div>
              <div style="margin-top: 5%">
                <q-btn
                  class="button-1"
                  @click="addNode()"
                  :label="$t('Confirm')"
                />
                <q-btn
                  class="button-2"
                  @click="addNodes = false"
                  :label="$t('Cancel')"
                />
              </div>
            </div>
          </q-card-section>
        </q-card>
      </q-dialog>
      <q-dialog v-model="importNodes">
        <q-card>
          <q-card-section class="row items-center">
            <div>
              <div style="width: 130px; margin-right: 30px">
                <div>Import Nodesystem</div>
              </div>
              <div style="width: 100%">
                <q-select
                  v-model="system"
                  :options="systemtype"
                  :label="$t('Type')"
                />
              </div>
              <div style="width: 100%">
                <q-input v-model="nodesystem" :label="$t('Nodes as JSON')" />
              </div>
              <div style="margin-top: 5%">
                <q-btn
                  class="button-1"
                  @click="addJSON()"
                  :label="$t('Confirm')"
                />
                <q-btn
                  class="button-2"
                  @click="importNodes = false"
                  :label="$t('Cancel')"
                />
              </div>
            </div>
          </q-card-section>
        </q-card>
      </q-dialog>
    </VueFlow>
  </q-page>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

// import { VueFlow, useVueFlow, Position, Background, Controls, MiniMap } from '@braks/vue-flow';
import { VueFlow, useVueFlow, Position } from '@vue-flow/core';
import { Background, Controls, MiniMap } from '@vue-flow/additional-components';

export default defineComponent({
  el: '#app',
  mixins: [],
  components: {
    VueFlow,
    Background,
    Controls,
    MiniMap,
  },
  data() {
    return {};
  },
  methods: {
    addNode() {
      var x1 = 100;
      var y1 = 200;
      var arraylength = 0;

      Array.from(this.elements).forEach((item: any) => {
        if ('dimensions' in item) {
          arraylength += 1;
        }
      });
      var lengthhandle = (arraylength + 1) / 5;
      if (lengthhandle >= 1) {
        y1 += 100 * Math.floor(lengthhandle);
        arraylength -= 5 * Math.floor(lengthhandle);
      }
      if (this.nodetype == 'Input') {
        this.elements.push({
          id: this.elements.length.toString(),
          type: 'input',
          label: this.nodename,
          position: { x: x1 + 200 * arraylength, y: y1 },
          sourcePosition: Position.Right,
          style: { border: '1px solid black' },
        });
      } else if (this.nodetype == 'Step') {
        this.elements.push({
          id: this.elements.length.toString(),
          label: this.nodename,
          position: { x: x1 + 200 * arraylength, y: y1 },
          sourcePosition: Position.Right,
          targetPosition: Position.Left,
        });
      } else if (this.nodetype == 'Output') {
        this.elements.push({
          id: this.elements.length.toString(),
          type: 'output',
          label: this.nodename,
          position: { x: x1 + 200 * arraylength, y: y1 },
          targetPosition: Position.Left,
          style: { border: '1px solid black' },
        });
      }

      this.addNodes = false;
      this.nodetype = 'Select';
      this.nodename = '';
    },
    removeNodes() {
      this.elements = [];
    },
    saveFlow() {
      logInfo(JSON.stringify(this.elements));
    },
    addJSON() {
      var remover = [
        'sourceX',
        'sourceY',
        'targetX',
        'targetY',
        'sourceHandle',
        'targetHandle',
      ];
      if (this.system == 'Random') {
        Array.from(JSON.parse(this.nodesystem)).forEach((item: any) => {
          if ('position' in item) {
            item.id = this.elements.length.toString();
          } else {
            var sourcename = item.sourceNode.label;
            var targetname = item.targetNode.label;
            this.getIDbyName(sourcename, 'sourceNode');
            item.source = this.id;
            this.getIDbyName(targetname, 'targetNode');
            item.target = this.id;
            item.id = 'e_' + item.source + '_' + item.target;
            // item.animated = true

            Array.from(item).forEach((key: any) => {
              if (key in remover) {
                delete item.key;
              }
            });
          }
          this.elements.push(item);
        });
      } else {
        Array.from(JSON.parse(this.nodesystem)).forEach((item: any) => {
          if ('sourceX' in item) {
            Array.from(item).forEach((key: any) => {
              if (key in remover) {
                delete item.key;
              }
            });
          }
          this.elements.push(item);
        });
      }
      this.importNodes = false;
      this.nodesystem = '';
      this.system = '';
      this.sortNodes();
    },
    runVisual() {
      Array.from(this.elements).every((item: any) => {
        if ('position' in item) {
          if (item.data == 'True' && item.style.backgroundColor == 'white') {
            item.style.backgroundColor = 'green';
          } else if (
            item.data == 'False' &&
            item.style.backgroundColor == 'white'
          ) {
            item.style.backgroundColor = 'red';
            return true;
          } else if (
            item.data == 'Unknown' &&
            item.style.backgroundColor == 'white'
          ) {
            item.style.backgroundColor = 'gray';
            return true;
          } else {
            return true;
          }
        } else {
          item.animated = true;
          return true;
        }
      });
    },
    sortNodes() {
      var x1 = 100;
      var y1 = 200;
      var arraylength = 0;
      Array.from(this.elements).forEach((item: any) => {
        if ('position' in item) {
          arraylength += 1;
        }
      });

      var checker = 0;
      var count = 0;

      Array.from(this.elements).forEach((item: any) => {
        if ('position' in item) {
          if (checker / 5 == 1) {
            count += 1;
            checker = 0;
            x1 = 100;
            y1 = 200;
            y1 += 100 * Math.floor(count);
            arraylength -= 5 * Math.floor(count);
          }
          item.position = { x: x1 + 200 * checker, y: y1 };
          if (item.type == 'input') {
            if ('style' in item) {
              item.style.border = '1px solid black';
              item.style.backgroundColor = 'white';
            } else {
              item.style = { border: '1px solid black' };
              item.style.backgroundColor = 'white';
            }
            item.sourcePosition = Position.Right;
          } else if (item.type == 'output') {
            if ('style' in item) {
              item.style.border = '1px solid black';
              item.style.backgroundColor = 'white';
            } else {
              item.style = { border: '1px solid black' };
              item.style.backgroundColor = 'white';
            }
            item.targetPosition = Position.Left;
          } else if (item.type == 'default') {
            if ('style' in item) {
              item.style.border = '1px solid black';
              item.style.backgroundColor = 'white';
            } else {
              item.style = { border: '1px solid black' };
              item.style.backgroundColor = 'white';
            }
            item.targetPosition = Position.Left;
            item.sourcePosition = Position.Right;
          }
          // if ('data' in item) {
          //   if (item.data == 'True' && item.style.backgroundColor == 'white') {
          //     item.style.backgroundColor = 'green';
          //   } else if (item.data == 'False' && item.style.backgroundColor == 'white') {
          //     item.style.backgroundColor = 'red';
          //   } else if (item.data == 'Unknown' && item.style.backgroundColor == 'white') {
          //     item.style.backgroundColor = 'gray';
          //   }
          // }
          checker += 1;
        } else {
          // var sourcename = item.sourceNode.label
          // var targetname = item.targetNode.label
          // Array.from(item).forEach((key: any) => {
          //     delete item.key
          // })
          // this.getIDbyName(sourcename, 'sourceNode')
          // item.source = this.id
          // this.getIDbyName(targetname, 'targetNode')
          // item.target = this.id
          // item.id = 'e_'+sourcename+'_'+targetname
          // item.animated = true
        }
      });
    },
    getIDbyName(name: string, type: string) {
      Array.from(this.elements).forEach((node: any) => {
        if (node.label == name) {
          this.id = node.id.toString();
        }
      });
    },
  },
  setup() {
    let nodetypes = ['Input', 'Step', 'Output'];
    let systemtype = ['Unique', 'Random'];
    const { onConnect, addEdges } = useVueFlow();
    onConnect((params) => addEdges([params]));
    return {
      elements: ref([] as any), // ref(initialElements)
      addNodes: ref(false),
      importNodes: ref(false),
      nodetype: ref('Select'),
      nodetypes: ref(nodetypes),
      nodename: ref(''),
      nodesystem: ref(''),
      system: ref(''),
      systemtype: ref(systemtype),
      id: ref(''),
    };
  },
});
</script>

